 tab='home';articleId='';settings:AppSettings={...defaults,seed:'#326b56',englishHumor:5,cantoneseHumor:5};extras:LocalExtras=structuredClone(extraDefaults);message='';releaseState='loading';release:any=null;releases:any[]=[];releasePage=1;releaseError='';category='';selected=new Set<string>();palette=false;voices:SpeechSynthesisVoice[]=[];revisions:Revision[]=[];vocabulary:Record<string,string>={};appearanceTarget='';appearanceSize=16;resetConfirm=false;activeSettings:AppSettings|null=null;workspaceState:WorkspaceState=readSiteWorkspace();
