 private applyAppearance(){const effective=this.activeSettings??this.settings;const now=new Date(),time=now.getHours()*60+now.getMinutes(),s=this.extras.schedule,minutes=(v:string)=>Number(v.slice(0,2))*60+Number(v.slice(3));let theme=effective.theme;const start=minutes(s.start),end=minutes(s.end);if(s.enabled&&start!==end&&(start<end?time>=start&&time<end:time>=start||time<end))theme=s.theme;const dark=theme==='dark'||theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;const materialTheme=themeFromSourceColor(argbFromHex(effective.seed));applyTheme(materialTheme,{target:document.documentElement,dark});for(const[name,tone]of Object.entries({'surface-container-low':dark?10:96,'surface-container':dark?12:94,'surface-container-high':dark?17:92}))document.documentElement.style.setProperty('--md-sys-color-'+name,hexFromArgb(materialTheme.palettes.neutral.tone(tone)));document.documentElement.style.colorScheme=dark?'dark':'light';document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.setProperty('--site-font-scale',String(effective.fontScale));document.documentElement.style.setProperty('--site-font',effective.fontFamily);document.documentElement.dataset.density=effective.density;document.documentElement.dataset.motion=effective.motion?'on':'off';document.documentElement.dataset.stimulation=effective.lowStimulation?'low':'normal';document.documentElement.lang=this.extras.school||this.settings.language==='en'?'en':'zh-HK';}
 private async readRelease(){this.releaseState='loading';try{const result=await fetch(api+'/releases/latest',{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(10000)});if(result.status===404){this.releaseState='none';return}if(!result.ok)throw Error(String(result.status));const release=await result.json();if(typeof release.tag_name!=='string'||!Array.isArray(release.assets)||release.draft||release.prerelease)throw Error('Invalid release');this.release=release;this.releaseState='ready'}catch{this.releaseState='error'}}
