 private search(key:SearchKey,label:string){const s=this.searchStates[key],change=()=>this.filter(key,this.valuesFor(key));return html`<mg-site-surface class="search-surface" aria-label=${label}><mg-site-layout class="search-row"><md-outlined-text-field label=${label} .value=${s.query} @input=${(e:any)=>{s.query=e.target.value;change()}}></md-outlined-text-field><md-outlined-button aria-expanded=${s.builder} @click=${()=>{s.builder=!s.builder;this.requestUpdate()}}>${this.copy('Regex builder','正則搜尋工具')}</md-outlined-button><md-text-button @click=${()=>{s.query='';s.error='';change()}}>${this.copy('Clear','清除')}</md-text-button></mg-site-layout>${s.builder?html`<mg-site-layout class="regex-panel"><label>${this.copy('Use regular expressions','使用正則表達式')}<md-switch .selected=${s.regex} @change=${(e:any)=>{s.regex=e.target.selected;change()}} aria-label=${this.copy('Use regular expressions','使用正則表達式')}></md-switch></label><md-outlined-text-field label=${this.copy('Flags (i, m, s, u)','旗標 (i, m, s, u)')} .value=${s.flags} @input=${(e:any)=>{s.flags=e.target.value;change()}}></md-outlined-text-field><mg-site-layout class="actions">${[['^','Start','開頭'],['$','End','結尾'],['.','Any character','任何字元'],['.*','Any text','任何文字'],['[a-z]','Character range','字元範圍'],['\\d','Digit','數字'],['(?:one|two)','Alternatives','其他選項'],['(text)','Capture','擷取'],['(?=text)','Lookahead','前瞻'],['{1,3}','Repeat','重複'],['\\b','Word boundary','字詞邊界']].map(([token,en,yue])=>html`<md-outlined-button title=${token} @click=${()=>{s.query+=token;s.regex=true;change()}}>${this.copy(en,yue)}</md-outlined-button>`)}</mg-site-layout><p class="small">${this.copy('JavaScript expressions run in a worker, with a 200 ms limit. Patterns and flags stay in this search. Matching defaults to case insensitive.','JavaScript 表達式喺背景工具執行，限時 200 毫秒。格式同旗標只用於呢個搜尋。預設不分大小寫。')}</p></mg-site-layout>`:nothing}${s.error?html`<p class="error" role="alert">${s.error}</p>`:nothing}</mg-site-surface>`}
