 private exportFile(data:unknown,name:string,type='application/json'){const text=typeof data==='string'?data:JSON.stringify(data,null,2),url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.notice(this.copy('Export prepared as UTF-8. Personal vocabulary and file metadata are excluded.','已準備 UTF-8 匯出，個人詞彙同檔案資料不會包含在內。'))}
