 private narrate(text:string){if(!window.speechSynthesis||!this.currentSettings.narrator)return;const language=this.extras.school?'en':this.currentSettings.narrationLanguage;this.speechQueue=[];for(const lang of language==='both'?['en','yue']: [language])this.speechQueue.push({text:this.speechCopies.get(text)?.[lang as 'en'|'yue']??text,language:lang as any});this.speakNext()}
